(async function(){const $=id=>document.getElementById(id),invoke=(c,a={})=>window.__TAURI__.core.invoke(c,a);await WhaleXDB.initDb();const id=new URLSearchParams(location.search).get('id');if(!id)return;let note=await WhaleXDB.getNote(id);if(!note)return;const libs=await WhaleXDB.listLibraries();$('library').innerHTML=libs.map(l=>`<option>${l.name}</option>`).join('');$('library').value=note.library;$('title').value=note.title;$('content').value=note.content;$('libLabel').textContent=`${note.library} · ${note.type}`;$('card').className='sticky-card '+(note.color||'blue');let timer;async function save(){await WhaleXDB.updateNote(id,{title:$('title').value,content:$('content').value,library:$('library').value,minimized:false});$('libLabel').textContent=`${$('library').value} · ${note.type}`;await WhaleXDB.notify()}['title','content'].forEach(k=>$(k).addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(save,220)}));$('library').onchange=save;$('minBtn').onclick=async()=>{await WhaleXDB.updateNote(id,{minimized:true});await WhaleXDB.notify();await invoke('minimize_sticky',{id})};$('closeBtn').onclick=async()=>{await WhaleXDB.updateNote(id,{sticky:false,minimized:false});await WhaleXDB.notify();await invoke('close_sticky',{id})};$('openMain').onclick=()=>invoke('show_main')})();